-- Refresh ALL course covers so the rendered title always matches the current
-- course name (store 0). Covers re-rendered 2026-07-17 from the live store-0
-- name + each product's own funding-badge tags, uploaded to R2. Also aligns
-- image_label/small_image_label/thumbnail_label and clears store-scoped
-- overrides of those 4 attributes so no per-store row shadows the new cover.
-- Map-table + JOIN pattern: SKUs absent on a partner DB are skipped. Idempotent.

DROP TABLE IF EXISTS mmd_cover_refresh_499;

CREATE TABLE mmd_cover_refresh_499 (
  sku VARCHAR(64) NOT NULL PRIMARY KEY,
  url VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


SELECT 4, a.attribute_id, 0, e.entity_id, m.url
FROM mmd_cover_refresh_499 m
JOIN catalog_product_entity e ON e.sku = m.sku
JOIN eav_attribute a ON a.entity_type_id = 4 AND a.attribute_code = 'course_image_url'
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 4, a.attribute_id, 0, e.entity_id, m.name
FROM mmd_cover_refresh_499 m
JOIN catalog_product_entity e ON e.sku = m.sku
JOIN eav_attribute a ON a.entity_type_id = 4 AND a.attribute_code IN ('image_label','small_image_label','thumbnail_label')
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE v FROM catalog_product_entity_varchar v
JOIN eav_attribute a ON a.attribute_id = v.attribute_id AND a.entity_type_id = 4
  AND a.attribute_code IN ('course_image_url','image_label','small_image_label','thumbnail_label')
JOIN catalog_product_entity e ON e.entity_id = v.entity_id
JOIN mmd_cover_refresh_499 m ON m.sku = e.sku
WHERE v.store_id <> 0;

DROP TABLE IF EXISTS mmd_cover_refresh_499;
